/**
 * Deterministic extraction from a PDF's text layer. No model, no network.
 *
 * This is the engine that runs when no AI key is configured, and it is also
 * what the AI engine's answers are grounded against. It reads documents the
 * way a careful person would: find a label, take the amount printed beside
 * it; find the table, read it column by column. It works on digitally produced
 * PDFs (the common case for pay applications generated by accounting or
 * billing software). It cannot read scans or see ink — and says so instead of
 * guessing: an absent value is null, an unseen signature is "unclear".
 */
import { parseMoney } from '@/lib/money';
import { parseLooseDate } from '@/lib/utils';
import { classifyWaiverType, recogniseStatutoryForm } from '@/server/compliance/jurisdictions';
import type {
  BBox,
  ClaimedField,
  DocType,
  DocumentSegment,
  Extracted,
  ExtractedLine,
  ExtractedPayApp,
  ExtractedWaiver,
  ExtractionResult,
  LineAmountField,
  Tri,
  WaiverType,
} from '@/server/types';
import { CLAIMED_FIELDS } from '@/server/types';
import { bboxOf, bboxOfLine, type Cell, type PageText, type PdfText, type TextLine } from './pdf-text';

export const TEXT_ENGINE = 'text-layer';

const none = <T>(): Extracted<T> => ({ value: null, confidence: 0, page: null });

// ── Money tokens ────────────────────────────────────────────────────────────

const MONEY_SRC = String.raw`\(?-?\$?\s?(?:\d{1,3}(?:,\d{3})+|\d+)\.\d{2}\)?-?|\(?-?\$?\s?\d{1,3}(?:,\d{3})+\)?`;
const isPercent = (s: string) => /^\(?-?\d{1,3}(\.\d+)?\s?%\)?$/.test(s.trim());

/** Money amounts in a string, skipping percentages. */
function moneyTokens(s: string): Array<{ raw: string; cents: number; index: number }> {
  const out: Array<{ raw: string; cents: number; index: number }> = [];
  const re = new RegExp(MONEY_SRC, 'g');
  let m: RegExpExecArray | null;
  while ((m = re.exec(s))) {
    const after = s.slice(m.index + m[0].length, m.index + m[0].length + 2);
    if (/^\s?%/.test(after)) continue;
    const cents = parseMoney(m[0]);
    if (cents !== null) out.push({ raw: m[0], cents, index: m.index });
  }
  return out;
}

/** A cell that is nothing but one amount (as in a table). */
function cellMoney(cell: Cell): number | null {
  const t = cell.text.trim();
  if (isPercent(t)) return null;
  if (!new RegExp(`^(?:${MONEY_SRC})$`).test(t)) return null;
  return parseMoney(t);
}

// ── Page classification ─────────────────────────────────────────────────────

export function classifyPage(page: PageText): { type: DocType; confidence: number } {
  const t = page.text.toLowerCase().replace(/\s+/g, ' ');
  const has = (re: RegExp) => re.test(t);
  // Column headings are usually stacked ("SCHEDULED" over "VALUE"), so match the words, not the phrase.
  if (has(/continuation sheet/) && has(/scheduled/)) return { type: 'continuation_sheet', confidence: 0.98 };
  if (has(/scheduled/) && has(/balance/) && has(/to finish/) && has(/this period|work completed/) && !has(/original contract sum/))
    return { type: 'continuation_sheet', confidence: 0.88 };
  if (has(/application and certificat(e|ion) for payment/) && has(/original contract (sum|amount)/)) return { type: 'pay_application', confidence: 0.98 };
  if (has(/original contract (sum|amount|value)/) && has(/current payment due|amount due this (application|period)|current amount due/))
    return { type: 'pay_application', confidence: 0.9 };
  if (has(/waiver and release|lien waiver|waiver of lien|release of lien/)) return { type: 'lien_waiver', confidence: 0.95 };
  if (has(/certificate of (liability )?insurance/)) return { type: 'insurance', confidence: 0.9 };
  if (has(/change order (no|number|#)/) && !has(/original contract sum/)) return { type: 'change_order', confidence: 0.8 };
  if (has(/\binvoice\b/) && has(/invoice (no|number|#|date)/)) return { type: 'invoice', confidence: 0.8 };
  if (has(/subcontract agreement/)) return { type: 'contract', confidence: 0.75 };
  return { type: 'other', confidence: 0.3 };
}

function segmentPages(pages: PageText[]): DocumentSegment[] {
  const segments: DocumentSegment[] = [];
  for (const page of pages) {
    const { type, confidence } = classifyPage(page);
    const last = segments[segments.length - 1];
    // Each waiver page stands alone; other types run on across pages.
    if (last && last.type === type && type !== 'lien_waiver' && last.pageEnd === page.page - 1) {
      last.pageEnd = page.page;
      last.confidence = Math.min(last.confidence, confidence);
    } else {
      segments.push({ type, pageStart: page.page, pageEnd: page.page, confidence });
    }
  }
  return segments;
}

// ── Label → value helpers ───────────────────────────────────────────────────

/**
 * Find the value printed for a label: on the same line to its right, or — when
 * the form stacks labels above values — directly underneath.
 */
function labelledText(page: PageText, labels: RegExp[]): { text: string; cell: Cell } | null {
  for (const label of labels) {
    for (let li = 0; li < page.lines.length; li++) {
      const line = page.lines[li]!;
      for (let ci = 0; ci < line.cells.length; ci++) {
        const cell = line.cells[ci]!;
        const m = label.exec(cell.text);
        if (!m || m.index > 2) continue;
        const rest = cell.text.slice(m.index + m[0].length).replace(/^[\s:#.]+/, '').trim();
        if (rest) return { text: rest, cell };
        const next = line.cells[ci + 1];
        if (next && next.x - (cell.x + cell.w) < 160 && !/:\s*$/.test(next.text)) return { text: next.text.trim(), cell: next };
        for (const below of page.lines.slice(li + 1, li + 3)) {
          const under = below.cells.find((c) => Math.abs(c.x - cell.x) < 6);
          if (under && !/:\s*$/.test(under.text)) return { text: under.text.trim(), cell: under };
        }
      }
    }
  }
  return null;
}

function textField(page: PageText, labels: RegExp[], confidence = 0.92): Extracted<string> {
  const hit = labelledText(page, labels);
  if (!hit || !hit.text) return none();
  return { value: hit.text, confidence, page: page.page, bbox: bboxOf(page, hit.cell), source: hit.text };
}

function dateField(page: PageText, labels: RegExp[]): Extracted<string> {
  const hit = labelledText(page, labels);
  if (!hit) return none();
  const m = /(\d{1,2}[/\-.]\d{1,2}[/\-.]\d{2,4}|\d{4}-\d{2}-\d{2}|[A-Za-z]{3,9}\.? \d{1,2},? \d{4}|\d{1,2} [A-Za-z]{3,9}\.?,? \d{4})/.exec(hit.text);
  const iso = parseLooseDate(m?.[1]);
  if (!iso) return { value: null, confidence: 0.2, page: page.page, bbox: bboxOf(page, hit.cell), source: hit.text };
  return { value: iso, confidence: 0.95, page: page.page, bbox: bboxOf(page, hit.cell), source: m![1] };
}

// ── Pay application (G702) ──────────────────────────────────────────────────

const AMOUNT_LABELS: Record<ClaimedField, { prefix: string; patterns: RegExp[] }> = {
  originalContractSum: { prefix: '1', patterns: [/original contract (sum|amount|value|price)/i] },
  netChangeOrders: { prefix: '2', patterns: [/net change by change orders?/i, /net changes? (by|from) change orders?/i, /approved change orders? to date/i] },
  contractSumToDate: { prefix: '3', patterns: [/contract sum to date/i, /(revised|current) contract (sum|amount|value)/i] },
  totalCompletedStored: { prefix: '4', patterns: [/total completed (&|and) stored to\s*date/i, /total (work )?completed (&|and) stored/i] },
  retainageWork: { prefix: 'a', patterns: [/%\s*of completed work/i, /retainage on completed work/i] },
  retainageStored: { prefix: 'b', patterns: [/%\s*of stored materials?/i, /retainage on stored materials?/i] },
  retainageTotal: { prefix: '5', patterns: [/total retainage/i, /retainage (withheld|held) to date/i] },
  totalEarnedLessRetainage: { prefix: '6', patterns: [/total earned less retainage/i] },
  lessPreviousCertificates: { prefix: '7', patterns: [/less previous (certificates|applications|payments|billings)/i, /previous certificates for payment/i] },
  currentPaymentDue: { prefix: '8', patterns: [/current payment due/i, /amount due this (application|period)/i, /current amount due/i] },
  balanceToFinish: { prefix: '9', patterns: [/balance to finish/i] },
};

function amountOnLine(page: PageText, line: TextLine, pattern: RegExp): { cents: number; cell: Cell; raw: string } | null {
  // Walk the cells; once the label has been seen, the right-most amount on the line is the value.
  let seen = false;
  let best: { cents: number; cell: Cell; raw: string } | null = null;
  for (const cell of line.cells) {
    let searchFrom = 0;
    if (!seen) {
      const m = pattern.exec(cell.text);
      if (!m) continue;
      seen = true;
      searchFrom = m.index + m[0].length;
    }
    for (const tok of moneyTokens(cell.text.slice(searchFrom))) best = { cents: tok.cents, cell, raw: tok.raw };
  }
  return best;
}

function amountField(page: PageText, field: ClaimedField, notes: string[]): Extracted<number> {
  const def = AMOUNT_LABELS[field];
  type Hit = { cents: number; cell: Cell; raw: string; numbered: boolean };
  const hits: Hit[] = [];
  for (const pattern of def.patterns) {
    for (let i = 0; i < page.lines.length; i++) {
      const line = page.lines[i]!;
      if (!pattern.test(line.text)) continue;
      const first = line.cells[0]?.text.trim() ?? '';
      const numbered = new RegExp(`^${def.prefix}[.)]?(\\s|$)`, 'i').test(first);
      let found = amountOnLine(page, line, pattern);
      if (!found) {
        // Value printed on the line below the label.
        const below = page.lines[i + 1];
        const cells = below?.cells.filter((c) => c.text.trim() !== '$') ?? [];
        if (below && cells.length > 0 && cells.every((c) => cellMoney(c) !== null)) {
          const c = cells[cells.length - 1]!;
          found = { cents: cellMoney(c)!, cell: c, raw: c.text };
        }
      }
      if (found) hits.push({ ...found, numbered });
    }
    if (hits.length > 0) break;
  }
  if (hits.length === 0) return none();
  const chosen = hits.find((h) => h.numbered) ?? hits[0]!;
  const conflicting = hits.some((h) => h.cents !== chosen.cents);
  if (conflicting && !chosen.numbered) notes.push(`More than one amount on page ${page.page} could be “${field}”; the first was used.`);
  return {
    value: chosen.cents,
    confidence: chosen.numbered ? 0.98 : conflicting ? 0.6 : 0.92,
    page: page.page,
    bbox: bboxOf(page, chosen.cell),
    source: chosen.raw.trim(),
  };
}

const ESIGN = [
  /electronically signed by:?\s+([A-Z][A-Za-z.'’ -]+?)(?:,| on |\s{2,}|$)/i,
  /docusigned by:?\s+([A-Z][A-Za-z.'’ -]+?)(?:,|\s{2,}|$)/i,
  /digitally signed by:?\s+([A-Z][A-Za-z.'’ -]+?)(?:,|\s{2,}|$)/i,
  /\/s\/\s*([A-Z][A-Za-z.'’ -]+?)(?:,|\s{2,}|$)/,
];

function signature(page: PageText, notes: string[], what: string): { signed: Extracted<Tri>; signerName: Extracted<string> } {
  for (const line of page.lines) {
    for (const cell of line.cells) {
      for (const re of ESIGN) {
        const m = re.exec(cell.text);
        if (m) {
          const bbox = bboxOf(page, cell);
          return {
            signed: { value: 'yes', confidence: 0.9, page: page.page, bbox, source: cell.text },
            signerName: { value: m[1]!.trim(), confidence: 0.9, page: page.page, bbox, source: m[1]!.trim() },
          };
        }
      }
    }
  }
  notes.push(`No electronic signature marker was found on the ${what}. A handwritten or stamped signature cannot be detected from the text layer, so it needs a visual check.`);
  return { signed: { value: 'unclear', confidence: 0.4, page: page.page }, signerName: none() };
}

function notarization(page: PageText): Extracted<Tri> {
  const idx = page.lines.findIndex((l) => /subscribed and sworn/i.test(l.text));
  if (idx < 0) return { value: 'no', confidence: 0.7, page: page.page, source: 'No notary acknowledgement block on the page.' };
  const block = page.lines.slice(idx, idx + 6);
  const blockText = block.map((l) => l.text).join(' ');
  const blanks = /_{4,}/.test(blockText);
  const notaryLine = page.lines.find((l) => /notary public/i.test(l.text));
  const named =
    !!notaryLine &&
    (notaryLine.cells.some((c) => !/notary public/i.test(c.text) && /[A-Za-z]{3,}/.test(c.text)) ||
      // the name is often printed just above the signature rule
      page.lines.some((l) => Math.abs(l.y - notaryLine.y) < 22 && l !== notaryLine && l.cells.some((c) => c.x > notaryLine.cells[0]!.x + 40 && /^[A-Z][A-Za-z.' -]{4,}$/.test(c.text))));
  const bbox = bboxOfLine(page, block[0]!);
  if (!blanks && named) return { value: 'yes', confidence: 0.8, page: page.page, bbox, source: block[0]!.text };
  return { value: 'unclear', confidence: 0.5, page: page.page, bbox, source: block[0]!.text };
}

function parsePayApplication(page: PageText, notes: string[]): ExtractedPayApp {
  const amounts = {} as Record<ClaimedField, Extracted<number>>;
  for (const field of CLAIMED_FIELDS) amounts[field] = amountField(page, field, notes);

  const appNo = labelledText(page, [/^application\s*(no|number|#)\.?:?/i, /^(pay(ment)?\s*)?app(lication)?\s*(no|number|#)\.?:?/i, /^requisition\s*(no|number|#)\.?:?/i]);
  const appNoMatch = appNo ? /\d{1,4}/.exec(appNo.text) : null;
  const sig = signature(page, notes, 'pay application');

  return {
    applicationNumber: appNoMatch
      ? { value: Number(appNoMatch[0]), confidence: 0.97, page: page.page, bbox: bboxOf(page, appNo!.cell), source: appNo!.text }
      : none(),
    periodTo: dateField(page, [/^period\s*to:?/i, /^(for\s*)?period\s*ending:?/i, /^billing\s*period\s*(to|ending):?/i]),
    applicationDate: dateField(page, [/^application\s*date:?/i, /^date\s*of\s*application:?/i]),
    projectName: textField(page, [/^project(\s*name)?:/i]),
    projectNumber: textField(page, [/^project\s*(no|number|#)\.?:?/i, /^job\s*(no|number|#)\.?:?/i]),
    contractorName: textField(page, [/^from\s*(sub)?contractor:?/i, /^from:/i, /^(sub)?contractor:/i]),
    toName: textField(page, [/^to\s*(owner|contractor|general contractor|gc):?/i, /^to:/i]),
    contractNumber: textField(page, [/^(sub)?contract\s*(no|number|#)\.?:?/i]),
    contractDate: dateField(page, [/^contract\s*date:?/i]),
    amounts,
    signed: sig.signed,
    signerName: sig.signerName,
    notarized: notarization(page),
  };
}

// ── Continuation sheet (G703) ───────────────────────────────────────────────

const LETTER_FIELD: Record<string, LineAmountField> = {
  C: 'scheduledValue',
  D: 'previous',
  E: 'thisPeriod',
  F: 'stored',
  G: 'total',
  H: 'balance',
  I: 'retainage',
};
const ITEM_NO = /^[A-Za-z]{0,3}[-.]?\d{1,4}[A-Za-z]?([.-]\d{1,3})*$/;

type SheetParse = { lines: ExtractedLine[]; totals: Partial<Record<LineAmountField, number | null>> | null };

function parseContinuationPage(page: PageText, notes: string[]): SheetParse {
  // Column letters row ("A B C D E F G H I"), present on the standard form.
  const letterLine = page.lines.find((l) => l.cells.filter((c) => /^[A-I]$/.test(c.text.trim())).length >= 5);
  const letters = letterLine
    ? letterLine.cells.filter((c) => /^[A-I]$/.test(c.text.trim())).map((c) => ({ letter: c.text.trim(), center: c.x + c.w / 2 }))
    : null;
  const headerY = letterLine?.y ?? page.lines.find((l) => /scheduled/i.test(l.text))?.y ?? 0;

  type Row = { line: TextLine; money: Array<{ cell: Cell; cents: number }>; label: Cell[] };
  const rows: Row[] = [];
  for (const line of page.lines) {
    if (line.y <= headerY) continue;
    const money: Row['money'] = [];
    const label: Cell[] = [];
    for (const cell of line.cells) {
      const cents = cellMoney(cell);
      if (cents !== null) money.push({ cell, cents });
      else if (!isPercent(cell.text) && cell.text.trim() !== '$') label.push(cell);
    }
    if (money.length >= 3) rows.push({ line, money, label });
  }
  if (rows.length === 0) return { lines: [], totals: null };

  // Numeric columns are right-aligned, so cluster the right edges.
  const edges = rows.flatMap((r) => r.money.map((m) => m.cell.x + m.cell.w)).sort((a, b) => a - b);
  const clusters: number[] = [];
  for (const e of edges) {
    if (clusters.length === 0 || e - clusters[clusters.length - 1]! > 8) clusters.push(e);
    else clusters[clusters.length - 1] = Math.max(clusters[clusters.length - 1]!, e);
  }

  let mapping: Array<LineAmountField | null>;
  let confidence: number;
  if (letters) {
    mapping = clusters.map((right) => {
      const owner = letters.filter((l) => l.center <= right + 2).sort((a, b) => b.center - a.center)[0];
      return owner ? (LETTER_FIELD[owner.letter] ?? null) : null;
    });
    confidence = 0.97;
  } else if (clusters.length === 7) {
    mapping = ['scheduledValue', 'previous', 'thisPeriod', 'stored', 'total', 'balance', 'retainage'];
    confidence = 0.88;
  } else if (clusters.length === 6) {
    mapping = ['scheduledValue', 'previous', 'thisPeriod', 'stored', 'total', 'balance'];
    confidence = 0.85;
  } else {
    notes.push(`The schedule of values on page ${page.page} has ${clusters.length} numeric columns and no column letters, so its columns could not be identified reliably.`);
    return { lines: [], totals: null };
  }
  const fieldAt = (cell: Cell): LineAmountField | null => {
    const right = cell.x + cell.w;
    let best = -1;
    let bestDist = Infinity;
    clusters.forEach((c, i) => {
      const d = Math.abs(c - right);
      if (d < bestDist) {
        bestDist = d;
        best = i;
      }
    });
    return bestDist <= 10 ? (mapping[best] ?? null) : null;
  };

  const lines: ExtractedLine[] = [];
  let totals: SheetParse['totals'] = null;
  for (const row of rows) {
    const values: Partial<Record<LineAmountField, number>> = {};
    for (const m of row.money) {
      const f = fieldAt(m.cell);
      if (f && values[f] === undefined) values[f] = m.cents;
    }
    const labelText = row.label.map((c) => c.text).join(' ').trim();
    if (/\b(grand\s+)?totals?\b/i.test(labelText) && !ITEM_NO.test(row.label[0]?.text.trim() ?? '')) {
      if (/sub-?total/i.test(labelText)) continue;
      totals = values;
      continue;
    }
    const first = row.label[0];
    const hasItemNo = !!first && ITEM_NO.test(first.text.trim()) && row.label.length > 1;
    const itemNo = hasItemNo ? first!.text.trim() : null;
    const description = (hasItemNo ? row.label.slice(1) : row.label).map((c) => c.text).join(' ').trim() || null;
    lines.push({
      itemNo,
      description,
      page: page.page,
      bbox: bboxOfLine(page, row.line),
      confidence,
      scheduledValue: values.scheduledValue ?? null,
      previous: values.previous ?? null,
      thisPeriod: values.thisPeriod ?? null,
      stored: values.stored ?? null,
      total: values.total ?? null,
      balance: values.balance ?? null,
      retainage: values.retainage ?? null,
    });
  }
  return { lines, totals };
}

// ── Lien waiver ─────────────────────────────────────────────────────────────

function parseWaiver(page: PageText, notes: string[]): ExtractedWaiver {
  const flat = page.text.replace(/\s+/g, ' ');
  const form = recogniseStatutoryForm(flat);
  const type: WaiverType = form?.type ?? classifyWaiverType(flat);
  const titleLine = page.lines.find((l) => /waiver/i.test(l.text));
  const here = <T>(value: T | null, confidence: number, source?: string | null, cell?: Cell): Extracted<T> =>
    value === null ? none() : { value, confidence, page: page.page, bbox: cell ? bboxOf(page, cell) : null, source: source ?? String(value) };
  const cellWith = (needle: string): Cell | undefined => {
    for (const line of page.lines) for (const cell of line.cells) if (cell.text.includes(needle)) return cell;
    return undefined;
  };
  const grab = (re: RegExp): string | null => re.exec(flat)?.[1]?.trim() ?? null;

  let amountRaw: string | null = null;
  let claimant: Extracted<string> = none();
  let customer: Extracted<string> = none();
  let owner: Extracted<string> = none();
  let job: Extracted<string> = none();
  let through: Extracted<string> = none();

  const money = `((?:${MONEY_SRC}))`;
  if (form?.state === 'CA') {
    claimant = textField(page, [/^name of claimant:?/i]);
    customer = textField(page, [/^name of customer:?/i]);
    job = textField(page, [/^job location:?/i]);
    owner = textField(page, [/^owner:?/i]);
    through = dateField(page, [/^through date:?/i]);
    amountRaw = grab(new RegExp(`amount of check:?\\s*\\$?\\s*${money}`, 'i')) ?? grab(new RegExp(`following (?:progress |final )?payment:?\\s*\\$?\\s*${money}`, 'i'));
  } else if (form?.state === 'TX') {
    amountRaw = grab(new RegExp(`in the sum of\\s*${money}`, 'i'));
    const payee = grab(/payable to (.+?) \(payee/i);
    const company = page.lines.find((l) => /\(company name\)/i.test(l.text))?.cells.find((c) => !/\(company name\)/i.test(c.text));
    claimant = company ? here(company.text.trim(), 0.92, company.text, company) : here(payee, 0.85);
    customer = here(grab(/check from (.+?) \(maker of check\)/i) ?? grab(/or to (.+?) \(person with whom signer contracted\)/i), 0.88);
    owner = here(grab(/property of (.+?) \(owner\)/i), 0.88);
    job = here(grab(/located at (.+?) \(location\)/i), 0.85);
  } else if (form?.state === 'FL') {
    amountRaw = grab(new RegExp(`(?:sum|amount) of\\s*${money}`, 'i'));
    const t = /furnished through (.+?) to (.+?) on the job of (.+?) to the following property/i.exec(flat);
    if (t) {
      const iso = parseLooseDate(t[1]!.trim());
      through = iso ? here(iso, 0.92, t[1]!.trim()) : { value: null, confidence: 0.2, page: page.page, source: t[1] };
      customer = here(t[2]!.trim(), 0.88);
      owner = here(t[3]!.trim(), 0.88);
    } else {
      const f = /furnished to (.+?) on the job of (.+?) to the following property/i.exec(flat);
      if (f) {
        customer = here(f[1]!.trim(), 0.88);
        owner = here(f[2]!.trim(), 0.88);
      }
    }
    const lienor = page.lines.find((l) => /\(lienor\)/i.test(l.text))?.cells.find((c) => !/\(lienor\)/i.test(c.text));
    if (lienor) claimant = here(lienor.text.trim(), 0.92, lienor.text, lienor);
  } else {
    claimant = textField(page, [/^(sub)?contractor:/i, /^claimant:?/i, /^name of claimant:?/i, /^company:?/i], 0.8);
    customer = textField(page, [/^(general )?contractor:/i, /^customer:?/i], 0.7);
    owner = textField(page, [/^owner:?/i], 0.8);
    job = textField(page, [/^project:?/i, /^job( location| name)?:?/i], 0.8);
    through = dateField(page, [/^through( date)?:?/i, /^period (ending|through):?/i]);
    amountRaw = labelledText(page, [/^amount:?/i, /^payment amount:?/i])?.text ?? grab(new RegExp(`(?:sum|amount) of\\s*${money}`, 'i'));
    if (customer.value && claimant.value && customer.value === claimant.value) customer = none();
  }

  const amountTok = amountRaw ? moneyTokens(amountRaw)[0] : undefined;
  const amountCell = amountTok ? cellWith(amountTok.raw.trim()) : undefined;
  if (!amountTok) notes.push(`No amount could be read from the lien waiver on page ${page.page}.`);

  const exceptions = grab(/(?:additional )?exceptions?:\s*(.+?)(?:\s{2,}|signature|date of signature|dated on|$)/i);
  const sig = signature(page, notes, 'lien waiver');
  const title = textField(page, [/^(title|claimant.?s title):?/i], 0.85);
  const signedDate = dateField(page, [/^date of signature:?/i, /^date:?/i, /^dated on/i]);

  return {
    page: page.page,
    waiverType: { value: type, confidence: form ? 0.96 : type === 'unknown' ? 0.3 : 0.7, page: page.page, bbox: titleLine ? bboxOfLine(page, titleLine) : null, source: titleLine?.text ?? null },
    formState: form ? { value: form.state, confidence: 0.95, page: page.page, source: form.title } : none(),
    title: titleLine ? { value: titleLine.text.trim(), confidence: 0.95, page: page.page, bbox: bboxOfLine(page, titleLine), source: titleLine.text } : none(),
    claimant,
    customer,
    owner,
    jobDescription: job,
    throughDate: through,
    amount: amountTok ? { value: amountTok.cents, confidence: form ? 0.95 : 0.85, page: page.page, bbox: amountCell ? bboxOf(page, amountCell) : null, source: amountTok.raw.trim() } : none(),
    exceptions: exceptions ? { value: exceptions, confidence: 0.8, page: page.page, source: exceptions } : none(),
    signed: sig.signed,
    signerName: sig.signerName,
    signerTitle: title,
    signedDate,
    notarized: notarization(page),
  };
}

// ── Entry point ─────────────────────────────────────────────────────────────

export function extractFromText(pdf: PdfText): ExtractionResult {
  const notes: string[] = [];
  const segments = segmentPages(pdf.pages);
  const result: ExtractionResult = { engine: TEXT_ENGINE, segments, notes };
  const pageOf = (n: number) => pdf.pages[n - 1]!;

  const payAppSeg = segments.find((s) => s.type === 'pay_application');
  if (payAppSeg) result.payApp = parsePayApplication(pageOf(payAppSeg.pageStart), notes);

  const sheetSegs = segments.filter((s) => s.type === 'continuation_sheet');
  if (sheetSegs.length > 0) {
    const lines: ExtractedLine[] = [];
    let totals: SheetParse['totals'] = null;
    for (const seg of sheetSegs) {
      for (let n = seg.pageStart; n <= seg.pageEnd; n++) {
        const parsed = parseContinuationPage(pageOf(n), notes);
        lines.push(...parsed.lines);
        if (parsed.totals) totals = parsed.totals;
      }
    }
    result.lines = lines;
    if (totals) result.lineTotals = totals;
    if (lines.length === 0) notes.push('A schedule of values was recognised but no line items could be read from it.');
  }

  const waiverSegs = segments.filter((s) => s.type === 'lien_waiver');
  if (waiverSegs.length > 0) result.waivers = waiverSegs.map((s) => parseWaiver(pageOf(s.pageStart), notes));

  return result;
}

/** Locate a money amount on a page so a value from another engine can be tied to a position. */
export function locateAmount(page: PageText, cents: number, nearLabel?: RegExp): { bbox: BBox; source: string } | null {
  let fallback: { bbox: BBox; source: string } | null = null;
  for (const line of page.lines) {
    for (const cell of line.cells) {
      if (!moneyTokens(cell.text).some((t) => t.cents === cents)) continue;
      const hit = { bbox: bboxOf(page, cell), source: cell.text.trim() };
      if (!nearLabel || nearLabel.test(line.text)) return hit;
      fallback ??= hit;
    }
  }
  return fallback;
}

export { AMOUNT_LABELS };
